cases.probe_gd:
extends SceneTree
const STORAGE = preload("res://scripts/infrastructure/storage/JsonFileStorage.gd")
func _init() -> void:
	var store = STORAGE.new(ProjectSettings.globalize_path("user://storage"))
	for path: String in ["save.json", "nested/save.json", "", "../save.json", "nested//save.json", "C:/save.json", "save" + String.chr(65533) + ".json"]:
		var result: Dictionary = store._validate_relative_path(path)
		print("NUL_ABLATION path=", path, " ok=", result.get("ok"), " code=", result.get("code", "ok"))
	print("NUL_ABLATION storage done")
	quit(0)

